				/* algorithm: 11.3  Encipherment RSA (standard) */
				/* algorithm: 11.31 Encipherment RSA (standard) with PKCS#1 padding */
				/* algorithm: 11.32 Encipherment RSA OAEP padding */
				*p++ = 0x89;
				*p++ = 0x02;
				*p++ = 0x11;
